(** The functions, decoded as a module. *)
Definition fflush_module : module := Eval vm_compute in
  code_module fflush_term.

(** The term decodes to the module. *)
Lemma fflush_decodes : decode_module fflush_term = Some fflush_module.
Proof. vm_compute. reflexivity. Qed.

(** The function named n of the module, or an empty one. *)
Definition fflush_fn (n : string) : func :=
  code_function fflush_module n.

(** glibc's `__GI__IO_fflush`. *)
Definition glibc__IO_fflush : func := Eval vm_compute in fflush_fn "__GI__IO_fflush".
